"""Job structure, event schema and whole-request policy budgets."""
import re

from syntax import PolicyError, parse

__all__ = ['Invalid', 'Job', 'validate_job', 'LIMITS', 'NAME_FORM']

U32 = 4294967295
LIMITS = {'images': 16, 'cells': 262144, 'units': 1024, 'contexts': 32768,
          'connections': 4096, 'packets': 32768, 'files': 8192}
NAME_FORM = re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}\\Z')

MAX_EVENTS = 200000
MAX_STAGES = 16
MAX_POLICY_BYTES = 8 * 1024 * 1024
MAX_ATOMS = 32768
MAX_PATH_SERVICES = 65536

SCHEMA = {
    'stage': {'epoch': 'positive', 'policy': 'text'},
    'commit': {'epoch': 'positive'},
    'retire': {'epoch': 'positive'},
    'spawn': {'unit': 'unit', 'service': 'name'},
    'clone': {'parent': 'unit', 'child': 'unit'},
    'exit': {'unit': 'unit'},
    'begin': {'unit': 'unit', 'rid': 'positive'},
    'finish': {'unit': 'unit', 'rid': 'positive'},
    'open': {'connection': 'pair'},
    'close': {'connection': 'pair'},
    'send': {'unit': 'unit', 'rid': 'positive', 'connection': 'pair',
             'stream': 'positive', 'destination': 'name'},
    'recv': {'connection': 'pair', 'stream': 'positive', 'unit': 'unit',
             'rid': 'positive', 'wire': 'wire'},
    'store': {'unit': 'unit', 'rid': 'positive', 'file': 'pair'},
    'load': {'file': 'pair', 'unit': 'unit', 'rid': 'positive'},
    'unlink': {'file': 'pair'},
    'inspect': {},
}


class Invalid(ValueError):
    """The job (or the whole request) is structurally out of contract."""


def _integer(value, low=1, high=U32):
    # Booleans are not integers: the contract insists on the exact type.
    return type(value) is int and low <= value <= high


def _typed(value, kind):
    if kind == 'positive':
        return _integer(value)
    if kind == 'name':
        return type(value) is str and NAME_FORM.match(value) is not None
    if kind == 'text':
        if type(value) is not str:
            return False
        value.encode('utf-8')          # an unpaired surrogate makes the job invalid
        return True
    if kind == 'wire':
        return value is None or (type(value) is str and len(value) <= 96)
    if kind == 'pair':
        return type(value) is list and len(value) == 2 and all(_integer(item) for item in value)
    if kind == 'unit':
        return (type(value) is list and len(value) == 3 and _integer(value[0], 0)
                and _integer(value[1]) and _integer(value[2]))
    return False


class Job:
    """A structurally valid job plus the request budget it consumes."""

    __slots__ = ('services', 'limits', 'events', 'policy_bytes', 'stages', 'atoms', 'symbols')

    def __init__(self, services, limits, events, policy_bytes, stages, atoms, symbols):
        self.services = services
        self.limits = limits
        self.events = events
        self.policy_bytes = policy_bytes
        self.stages = stages
        self.atoms = atoms
        self.symbols = symbols


def _check(job):
    if type(job) is not dict or set(job) != {'services', 'limits', 'events'}:
        raise Invalid('job keys')
    services = job['services']
    limits = job['limits']
    events = job['events']
    if type(services) is not list or not 1 <= len(services) <= 16:
        raise Invalid('services')
    names = set()
    labels = set()
    for service in services:
        if type(service) is not dict or set(service) != {'name', 'label'}:
            raise Invalid('service keys')
        if not _typed(service['name'], 'name') or not _integer(service['label'], 1, U32 - 1):
            raise Invalid('service fields')
        if service['name'] in names or service['label'] in labels:
            raise Invalid('service uniqueness')
        names.add(service['name'])
        labels.add(service['label'])
    if type(limits) is not dict or set(limits) != set(LIMITS):
        raise Invalid('limits keys')
    for key, value in limits.items():
        if not _integer(value, 1, LIMITS[key]):
            raise Invalid('limits values')
    if type(events) is not list or len(events) > MAX_EVENTS:
        raise Invalid('events')
    for event in events:
        if type(event) is not dict or type(event.get('op')) is not str:
            raise Invalid('event shape')
        fields = SCHEMA.get(event['op'])
        if fields is None or set(event) != set(fields) | {'op'}:
            raise Invalid('event fields')
        for key, kind in fields.items():
            if not _typed(event[key], kind):
                raise Invalid('event field type')
    return services, limits, events


def validate_job(job):
    """Return the validated Job, or raise Invalid.

    Policy occurrence counting follows the syntax paragraph of the contract:
    a syntactically valid string inside the per-string bounds contributes to
    the request totals even when it names an unregistered service or its stage
    is later rejected, while an invalid string contributes nothing.
    """
    services, limits, events = _check(job)
    policy_bytes = 0
    stages = 0
    atoms = 0
    symbols = 0
    for event in events:
        if event['op'] != 'stage':
            continue
        stages += 1
        policy = event['policy']
        policy_bytes += len(policy.encode('utf-8'))
        try:
            _rules, counted, paths = parse(policy)
        except PolicyError:
            continue
        except RecursionError:
            raise Invalid('policy parse')
        atoms += counted
        symbols += paths
    return Job(services, limits, events, policy_bytes, stages, atoms, symbols)


def within_totals(total_events, total_bytes, total_stages, total_atoms, total_symbols):
    return not (total_events > MAX_EVENTS or total_bytes > MAX_POLICY_BYTES
                or total_stages > MAX_STAGES or total_atoms > MAX_ATOMS
                or total_symbols > MAX_PATH_SERVICES)
